using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages.Assets;public class EditModel(AssetForgeDbContext db):PageModel{[BindProperty]public Asset Input{get;set;}=new();public SelectList Categories{get;set;}=null!;public SelectList Locations{get;set;}=null!;public SelectList Departments{get;set;}=null!;public async Task OnGetAsync(int? id){if(id.HasValue)Input=await db.Assets.FindAsync(id)??new();await Lists();}public async Task<IActionResult> OnPostAsync(){if(!ModelState.IsValid){await Lists();return Page();}if(Input.Id==0){Input.AssetTag=await NextTag();db.Assets.Add(Input);db.AuditEvents.Add(new AuditEvent{Asset=Input,Action="Created",Details=$"Asset {Input.Name} created",PerformedBy=User.Identity?.Name??"admin"});}else{var row=await db.Assets.FindAsync(Input.Id);if(row is null)return NotFound();var tag=row.AssetTag;db.Entry(row).CurrentValues.SetValues(Input);row.AssetTag=tag;row.UpdatedUtc=DateTime.UtcNow;db.AuditEvents.Add(new AuditEvent{AssetId=row.Id,Action="Updated",Details="Asset details updated",PerformedBy=User.Identity?.Name??"admin"});}await db.SaveChangesAsync();return RedirectToPage("/Assets/Index");}private async Task Lists(){Categories=new(await db.Categories.OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Locations=new(await db.Locations.OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Departments=new(await db.Departments.OrderBy(x=>x.Name).ToListAsync(),"Id","Name");}private async Task<string> NextTag()=>await db.Assets.MaxAsync(x=>(int?)x.Id) is int n?$"AF-{n+102:000000}":"AF-000001";}
